// Reads input constraints from the API's own OpenAPI document (generated by
// `python -m src.product.export`), so the form validates exactly what the server enforces.

import openapi from "@/data/openapi.json";
import type { PlayerField } from "@/lib/api/types";

interface SchemaProp {
  type?: string;
  minimum?: number;
  maximum?: number;
  default?: unknown;
  enum?: string[];
  anyOf?: SchemaProp[];
  description?: string;
  title?: string;
}

export interface Constraint {
  type: "number" | "integer" | "string";
  min?: number;
  max?: number;
  nullable: boolean;
  required: boolean;
  default?: unknown;
  enum?: string[];
  description?: string;
}

const playerSchema = openapi.components.schemas.PlayerFeatures as unknown as {
  properties: Record<string, SchemaProp>;
  required: string[];
  additionalProperties: boolean;
};

function toConstraint(name: string, prop: SchemaProp): Constraint {
  const options = prop.anyOf ?? [prop];
  const main = options.find((o) => o.type && o.type !== "null") ?? {};
  return {
    type: (main.type as Constraint["type"]) ?? "string",
    min: main.minimum,
    max: main.maximum,
    nullable: options.some((o) => o.type === "null"),
    required: playerSchema.required.includes(name),
    default: prop.default,
    enum: main.enum,
    description: prop.description,
  };
}

export const PLAYER_CONSTRAINTS: Record<string, Constraint> = Object.fromEntries(
  Object.entries(playerSchema.properties).map(([name, prop]) => [name, toConstraint(name, prop)]),
);

export const CONTRACT_FIELDS = Object.keys(playerSchema.properties) as PlayerField[];

export function constraintFor(field: PlayerField): Constraint {
  const c = PLAYER_CONSTRAINTS[field];
  if (!c) throw new Error(`Field ${field} is not in the API contract`);
  return c;
}

export const API_VERSION = openapi.info.version;
